---@class UICultivateAppearanceDialog
---@field ListView                      	SuperScrollView.LoopListView2
---@field BtnArrowRightSkin             	UnityEngine.UI.Button
---@field BtnArrowLeftSkin              	UnityEngine.UI.Button
---@field AcquireButton                 	UnityEngine.UI.Button
---@field ReplaceButton                 	UnityEngine.UI.Button
---@field ImgCurrent                    	UnityEngine.RectTransform
---@field BtnEffects                    	UnityEngine.UI.Button
---@field BtnPhotograph                 	UnityEngine.UI.Button
---@field BtnDialogue                   	UnityEngine.UI.Button
---@field TxtDescribe                   	UnityEngine.RectTransform
---@field TxtCardName                   	UnityEngine.RectTransform
---@field TxtRoleName                   	UnityEngine.RectTransform
---@field BtnArrowRightRole             	UnityEngine.RectTransform
---@field BtnArrowLeftRole              	UnityEngine.RectTransform
local UICultivateAppearanceDialog = Class("UICultivateAppearanceDialog")
function UICultivateAppearanceDialog:__init()
    self.data = nil
    self.selectIndex = -1
    -- self.roleLoader = nil
    self.skin = nil --卡牌对应的所有皮肤id
    self.selectIndexSkin = -1 --当前选择皮肤的索引，从1开始 由于首尾补了空位所以首尾在使用时要判断去掉
    self.preSelectIndexSkin = -1 --上一个选择的皮肤索引，用于记录变大变小

end

function UICultivateAppearanceDialog:__delete()
    self.controller = nil
    self.data = nil
    self.selectIndex = -1
    -- self.roleLoader = nil
    self.skin = nil
    self.selectIndexSkin = -1
    self.preSelectIndexSkin = -1

end


function UICultivateAppearanceDialog:Awake()
    self.data = KCookie.Get(Constants.UICacheDataKeys.UICultivateMainCards)
    --printInfo("UICultivateAppearanceDialog--Awake--cardData--")
    --printInfo(table.dump(self.data))
    --printInfo("UICultivateAppearanceDialog--Awake--cardData--")
    self.selectIndex = KCookie.Get(Constants.UICacheDataKeys.UICultivateMainPosition)

end

function UICultivateAppearanceDialog:OnFocus(focus)
end

function UICultivateAppearanceDialog:OnInitialize()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        self:InitSkinInfo()
        -- self.roleLoader = RoleLoader.New()
        -- self.roleLoader:GetNew(self:GetSelectCardDojo())
        SetButtonAction(self.AcquireButton, Bind(self, self.BtnAcquireAction))
        SetButtonAction(self.ReplaceButton, Bind(self, self.BtnReplaceAction))

        if #self.data <= 1 then --左侧角色切换
            KTool.SetActive(self.BtnArrowLeftRole.gameObject, false)
            KTool.SetActive(self.BtnArrowRightRole.gameObject, false)
        else
            SetButtonAction(self.BtnArrowLeftRole, Bind(self, self.BtnArrowLeftRoleAction))
            SetButtonAction(self.BtnArrowRightRole, Bind(self, self.BtnArrowRightRoleAction))
        end

        if #self.skin <= 1 then --右侧皮肤切换
            KTool.SetActive(self.BtnArrowLeftSkin.gameObject, false)
            KTool.SetActive(self.BtnArrowRightSkin.gameObject, false)
        else
            SetButtonAction(self.BtnArrowLeftSkin, Bind(self, self.BtnArrowLeftSkinAction))
            SetButtonAction(self.BtnArrowRightSkin, Bind(self, self.BtnArrowRightSkinAction))
        end
        self:RefreshLeftPanelUI()
        self:InitSkinListView()
        self:RefreshRightPanelUI()
    end))
    return coWait
end

function UICultivateAppearanceDialog:InitSkinInfo()
    self.skin = CardConfMgr:GetCardSkinsByCardId(self.data[self.selectIndex].cardId)
    self.selectIndexSkin = self:GetIndexById(self.data[self.selectIndex].cardSkin) + 1--后面补了空位
    ---首尾补一个空位
    local t = {[1] = ""}
    for k, v in pairs(self.skin) do
        table.insert(t, v)
    end
    table.insert(t, "")
    self.skin = t
end

---换角色箭头 ←
function UICultivateAppearanceDialog:BtnArrowLeftRoleAction()
    if self.selectIndex <= 1 then
        return
    end
    self.selectIndex = self.selectIndex - 1
    -- self.roleLoader:Reload(self:GetSelectCardDojo())
    self:RefreshLeftPanelUI()
    self:ReloadSkinListView()
    self:RefreshRightPanelUI()
end

---换角色箭头 →
function UICultivateAppearanceDialog:BtnArrowRightRoleAction()
    if self.selectIndex >= #self.data then
        return
    end
    self.selectIndex = self.selectIndex + 1
    -- self.roleLoader:Reload(self:GetSelectCardDojo())
    self:RefreshLeftPanelUI()
    self:ReloadSkinListView()
    self:RefreshRightPanelUI()
end

---换皮肤箭头 ←
function UICultivateAppearanceDialog:BtnArrowLeftSkinAction()
    if self.selectIndexSkin <= 1 + 1 then
        return
    end
    self.preSelectIndexSkin = self.selectIndexSkin
    self.selectIndexSkin = self.selectIndexSkin - 1
    self.ListView:SetSnapTargetItemIndex(self.selectIndexSkin - 1)

    --更换左侧模型
    self:RefreshRightPanelUI()
end

---换皮肤箭头 →
function UICultivateAppearanceDialog:BtnArrowRightSkinAction()
    if self.selectIndexSkin >= #self.skin - 1 then
        return
    end
    self.preSelectIndexSkin = self.selectIndexSkin
    self.selectIndexSkin = self.selectIndexSkin + 1
    self.ListView:SetSnapTargetItemIndex(self.selectIndexSkin - 1)

    --更换左侧模型
    self:RefreshRightPanelUI()
end

---皮肤列表下面的当前、替换，获取三个按钮，三个只能显示一个
function UICultivateAppearanceDialog:SkinBtnChange()
    local cardSkinComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CardSkinComponent)
    if cardSkinComponent:IsHasSkin(self.skin[self.selectIndexSkin]) then --当前选择皮肤的皮肤id
        if checkNumber(self.skin[self.selectIndexSkin]) == checkNumber(self.data[self.selectIndex].cardSkin) then --已拥有且为当前使用，激活当前图片
            KTool.SetActive(self.ImgCurrent.gameObject, true)
            KTool.SetActive(self.ReplaceButton.gameObject, false)
            KTool.SetActive(self.AcquireButton.gameObject, false)
        else--已拥有但未使用，激活替换按钮
            KTool.SetActive(self.ImgCurrent.gameObject, false)
            KTool.SetActive(self.ReplaceButton.gameObject, true)
            KTool.SetActive(self.AcquireButton.gameObject, false)
        end
    else--未拥有，激活获取按钮
        KTool.SetActive(self.ImgCurrent.gameObject, false)
        KTool.SetActive(self.ReplaceButton.gameObject, false)
        KTool.SetActive(self.AcquireButton.gameObject, true)
    end
end

---获取皮肤按钮点击后的弹窗，还没有对应UI
function UICultivateAppearanceDialog:BtnAcquireAction()

end

---发送请求替换皮肤，将当前皮肤设置到服务器
function UICultivateAppearanceDialog:BtnReplaceAction()

end

---左边换角色箭头的显示隐藏
function UICultivateAppearanceDialog:RefreshLeftPanelUI()
    if self.selectIndex <= 1 then
        KTool.SetActive(self.BtnArrowLeftRole.gameObject, false)
        KTool.SetActive(self.BtnArrowRightRole.gameObject, true)
    elseif self.selectIndex >= #self.data then
        KTool.SetActive(self.BtnArrowLeftRole.gameObject, true)
        KTool.SetActive(self.BtnArrowRightRole.gameObject, false)
    else
        KTool.SetActive(self.BtnArrowLeftRole.gameObject, true)
        KTool.SetActive(self.BtnArrowRightRole.gameObject, true)
    end
end

---右边面板UI刷新，包括箭头，描述，下方选择按钮以及三个图标
function UICultivateAppearanceDialog:RefreshRightPanelUI()
    ---箭头
    if #self.skin > 1 + 2 then--首尾补了空位所以加二
        if self.selectIndexSkin <= 1 + 1 then
            KTool.SetActive(self.BtnArrowLeftSkin.gameObject, false)
            KTool.SetActive(self.BtnArrowRightSkin.gameObject, true)
        elseif self.selectIndexSkin >= #self.skin - 1 then
            KTool.SetActive(self.BtnArrowLeftSkin.gameObject, true)
            KTool.SetActive(self.BtnArrowRightSkin.gameObject, false)
        else
            KTool.SetActive(self.BtnArrowLeftSkin.gameObject, true)
            KTool.SetActive(self.BtnArrowRightSkin.gameObject, true)
        end
    else
        KTool.SetActive(self.BtnArrowLeftSkin.gameObject, false)
        KTool.SetActive(self.BtnArrowRightSkin.gameObject, false)
    end
    ---描述及三个图标
    local curSkinInfo = CardConfMgr:GetCardSkinBySkinId(self.skin[self.selectIndexSkin])
    self.TxtRoleName.text = curSkinInfo.desc
    self.TxtCardName.text = curSkinInfo.name
    KTool.SetActive(self.BtnDialogue.gameObject, checkNumber(curSkinInfo.dialogueTag) == 1)
    KTool.SetActive(self.BtnPhotograph.gameObject,checkNumber(curSkinInfo.goodOpinionTag) == 1)
    KTool.SetActive(self.BtnEffects.gameObject, checkNumber(curSkinInfo.effectTag) == 1)
    local desc = CfUtils.GetCfVo(AutoIds.IdSetting711, "SkinGoodsVo", self.skin[self.selectIndexSkin]).desc
    self.TxtDescribe.text = desc
    ---当前替换获取按钮显示一个
    self:SkinBtnChange()
end

---实例化皮肤列表
function UICultivateAppearanceDialog:InitSkinListView()
    self.ListView:InitListView(#self.skin, Bind(self, self.OnGetItemByIndex))
    self.ListView.mOnSnapNearestChanged = Bind(self, self.OnListViewSnapTargetChanged)
    --self.ListView.mOnSnapItemFinished = Bind(self, self.OnListViewSnapTargetChangedFinished)
end

---刷新皮肤列表
function UICultivateAppearanceDialog:ReloadSkinListView()
    self:InitSkinInfo()
    GameUtils.ReloadData(self.ListView, #self.skin)
end


---皮肤列表中每一个小图标（子节点）
function UICultivateAppearanceDialog:OnGetItemByIndex(listView, index)
    if index < 0 then
        return nil
    end
    local cell = listView:NewListViewItem(UIIconCellName)
    if index == 0 or index == #self.skin - 1 then --首位补的空位直接返回掉
        KTool.SetActive(cell.transform:Find("Item"), false)
        return cell
    end
    local cardSkinComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CardSkinComponent)
    local skinInfo = CardConfMgr:GetCardSkinBySkinId(self.skin[index + 1]) --前面补了一个空位所以加一
    KTool.SetActive(cell.transform:Find("Item"), true)
    cell.gameObject.name = "cell"..index --用作辅助
    local imgNode = cell.transform:Find("Item/Mask/ImgIconHalfRole")
    local unlockNode = cell.transform:Find("Item/ImgNotOpen")
    KTool.GetOrAddComponent(imgNode.gameObject, typeof(ImageAlterable)):LoadSprite(skinInfo.cardHeadList)
    KTool.SetActive(unlockNode.gameObject, not cardSkinComponent:IsHasSkin(self.skin[index + 1])) --前面补了一个空位所以加一
    return cell
end

---皮肤列表中间的放大缩小
function UICultivateAppearanceDialog:OnListViewSnapTargetChanged(listView, acell)
    printInfo("UICultivateAppearanceDialog:OnListViewSnapTargetChanged")
    if self.selectIndexSkin < 0 or self.selectIndexSkin >= #self.skin then
        return
    end
    local centerCell = nil
    local subCell = nil

    centerCell = listView:GetShownItemByItemIndex(self.selectIndexSkin - 1)
    subCell = listView:GetShownItemByItemIndex(self.preSelectIndexSkin - 1)
    CfUtils.SetScale(centerCell.transform:Find("Item").gameObject, CENTER_SCALE)
    if not isNull(subCell) then
        CfUtils.SetScale(subCell.transform:Find("Item").gameObject, SUB_SCALE)
    end
end

