---根据皮肤id获取索引
function UICultivateAppearanceDialog:GetIndexById(skinId)
    if checkNumber(skinId) then
        return table.keyof(self.skin, skinId)
    end
    return nil
end

function UICultivateAppearanceDialog:GetSelectCardDojo()
    local cardDojo = self.data[self.selectIndex]
    return cardDojo
end

function UICultivateAppearanceDialog:OnFinalize()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(
            util.cs_generator(
                    function()
                        --self.roleLoader:Destroy()
                        ----移除不需要的资源
                        if not isNull(self) then
                            self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
                            self:Delete()
                            self = nil --lua层的gc需要
                        end
                    end
            )
    )
    return coWait
end

return UICultivateAppearanceDialog